```yaml
name: PR Title Check

on:
  pull_request:
    types: [opened, edited, synchronize]

jobs:
  check-title:
    runs-on: ubuntu-latest
    steps:
      - name: Check PR Title Format
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const pr = context.payload.pull_request;
            const title = pr.title;
            const regex = /^(?:\((?:feat|fix|docs|style|refactor|test|chore|revert)\)|\((?:perf|ci|build|deps)\)) .+ \[DA-\d+\]$/;

            if (!regex.test(title)) {
              const errorMessage = `PR title "${title}" does not match the required format: "(TYPE) description [TASK-ID]" where TYPE is one of: feat, fix, docs, style, refactor, test, chore, revert, perf, ci, build, deps`;

              core.setFailed(errorMessage);

              // Comment on the PR with the error message
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: pr.number,
                body: `❌ PR title does not match the required format:\n\n\`${errorMessage}\`\n\nPlease update your PR title to follow this pattern: \`<type> <description> [TASK-ID]\`` 
              });
            }
```

